using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class SpatialGuides {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/B5/";static Transform root,group;static JObject plan;static float labFloor;static Dictionary<string,Material> paints=new Dictionary<string,Material>();static Dictionary<string,Material> labels=new Dictionary<string,Material>();static List<string> changedRenderers=new List<string>();
 static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string PathOf(Transform t)=>t.parent?PathOf(t.parent)+"/"+t.name:t.name;
 static Vector3 V(JToken p)=>new Vector3((float)p[0],-82,(float)p[1]);
 static Vector3 Floor(Vector3 p){var hits=Physics.RaycastAll(new Vector3(p.x,-81.65f,p.z),Vector3.down,.6f,~0,QueryTriggerInteraction.Ignore).Where(h=>h.normal.y>.8f&&h.collider.transform.IsChildOf(root)).ToArray();if(hits.Length==0)throw new Exception("Missing floor "+p);float y=Mathf.Max(-81.99f,hits.Max(h=>h.point.y));if(Vector2.Distance(new Vector2(p.x,p.z),new Vector2(-15,-10))<9.95f)y=Mathf.Max(y,labFloor);p.y=y+.0035f;return p;}
 class Geo {public List<Vector3> v=new List<Vector3>();public List<int> t=new List<int>();public List<Vector2> uv=new List<Vector2>();public void Quad(Vector3 a,Vector3 b,Vector3 c,Vector3 d){int k=v.Count;v.AddRange(new[]{Floor(a),Floor(b),Floor(c),Floor(d)});uv.AddRange(new[]{new Vector2(0,0),new Vector2(1,0),new Vector2(0,1),new Vector2(1,1)});t.AddRange(new[]{k,k+2,k+1,k+1,k+2,k+3});}public void Rect(Vector3 p,Vector3 f,float w,float len){var r=Vector3.Cross(Vector3.up,f).normalized*w*.5f;var d=f.normalized*len*.5f;Quad(p-r-d,p+r-d,p-r+d,p+r+d);}public void Stroke(Vector3 a,Vector3 b,float w){var r=Vector3.Cross(Vector3.up,(b-a).normalized)*w*.5f;Quad(a-r,a+r,b-r,b+r);}public void Ribbon(Vector3[] ps,float w){int start=v.Count;for(int i=0;i<ps.Length;i++){Vector3 a=(ps[i]-ps[Mathf.Max(0,i-1)]).normalized,b=(ps[Mathf.Min(ps.Length-1,i+1)]-ps[i]).normalized,d=(a+b).normalized;if(d==Vector3.zero)d=i==0?b:a;var r=Vector3.Cross(Vector3.up,d).normalized*w*.5f;v.Add(Floor(ps[i]-r));v.Add(Floor(ps[i]+r));uv.Add(new Vector2(0,i*.08f));uv.Add(new Vector2(1,i*.08f));if(i>0){int k=start+2*i;t.AddRange(new[]{k-2,k,k-1,k-1,k,k+1});}}}}
 static Mesh Save(string n,Geo g){string path=E+n+".asset";var m=AssetDatabase.LoadAssetAtPath<Mesh>(path);bool exists=m;if(!m)m=new Mesh{name=n};else m.Clear();m.SetVertices(g.v);m.SetUVs(0,g.uv);m.SetTriangles(g.t,0);m.RecalculateNormals();m.RecalculateTangents();m.RecalculateBounds();m.UploadMeshData(false);if(exists){EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);}else AssetDatabase.CreateAsset(m,path);return m;}
 static void Add(string n,Geo geo,Material mat){var g=new GameObject(n);g.transform.SetParent(group,false);g.AddComponent<MeshFilter>().sharedMesh=Save(n,geo);var rr=g.AddComponent<MeshRenderer>();rr.sharedMaterial=mat;rr.shadowCastingMode=ShadowCastingMode.Off;rr.reflectionProbeUsage=ReflectionProbeUsage.Off;}
 static Material Mat(string n,Color color,string texture=null){var path=E+"Materials/"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.name=n;m.SetColor("_BaseColor",color);m.SetFloat("_Metallic",0);m.SetFloat("_Smoothness",.16f);m.SetFloat("_SpecularHighlights",0);m.SetFloat("_Cull",2);m.DisableKeyword("_EMISSION");m.SetColor("_EmissionColor",Color.black);m.globalIlluminationFlags=MaterialGlobalIlluminationFlags.EmissiveIsBlack;if(texture!=null){m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(E+"Textures/"+texture+".png"));m.SetFloat("_AlphaClip",1);m.SetFloat("_Cutoff",.35f);m.EnableKeyword("_ALPHATEST_ON");m.SetOverrideTag("RenderType","TransparentCutout");m.renderQueue=2450;}else m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(E+"Textures/CW_Paint_Base.png"));EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);return m;}
 static void Assign(Renderer r,Material m){r.sharedMaterial=m;changedRenderers.Add(PathOf(r.transform));}
 static void Marker(Geo g,Vector3 p,Vector3 f,string type){var r=Vector3.Cross(Vector3.up,f).normalized;if(type=="circle"){for(int i=0;i<24;i++){float a=i*Mathf.PI*2/24,b=(i+1)*Mathf.PI*2/24;g.Quad(p+(r*Mathf.Cos(a)+f*Mathf.Sin(a))*.065f,p+(r*Mathf.Cos(a)+f*Mathf.Sin(a))*.09f,p+(r*Mathf.Cos(b)+f*Mathf.Sin(b))*.065f,p+(r*Mathf.Cos(b)+f*Mathf.Sin(b))*.09f);}}else if(type=="double"){foreach(float x in new[]{-.07f,.07f})g.Rect(p+r*x,f,.026f,.24f);}else{var pts=type=="diamond"?new[]{p+f*.09f,p+r*.09f,p-f*.09f,p-r*.09f}:new[]{p-r*.075f-f*.075f,p+r*.075f-f*.075f,p+r*.075f+f*.075f,p-r*.075f+f*.075f};for(int i=0;i<4;i++)g.Stroke(pts[i],pts[(i+1)%4],.025f);}}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var prior=root.Find("Spatial_DestinationGuidance");if(prior){File.Copy(Path.GetFullPath(s.path),Path.Combine(Path.GetTempPath(),"AfterSeconds_B5_GuideClearance_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity"));UnityEngine.Object.DestroyImmediate(prior.gameObject);}plan=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_SpatialRefinement/guidance.json"));labFloor=root.Find("C01_Experiment_Art/S1_FloorFinish_02").GetComponent<Renderer>().bounds.max.y;Physics.SyncTransforms();
 foreach(var file in Directory.GetFiles(Path.Combine(Application.dataPath,"Afrer_Seconds/05.Model/Environment/B5/Textures"),"SF_*.png")){string path=E+"Textures/"+Path.GetFileName(file);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var ti=(TextureImporter)AssetImporter.GetAtPath(path);ti.alphaIsTransparency=true;ti.mipmapEnabled=true;ti.maxTextureSize=2048;ti.filterMode=FilterMode.Trilinear;ti.wrapMode=TextureWrapMode.Clamp;ti.SaveAndReimport();}
 foreach(var entry in (JObject)plan["destinations"]){Color c;ColorUtility.TryParseHtmlString((string)entry.Value["color"],out c);paints[entry.Key]=Mat("SF_Paint_"+entry.Key,c);labels[entry.Key]=Mat("SF_Label_"+entry.Key,Color.white,"SF_Floor_"+entry.Key);}
 var g0=new GameObject("Spatial_DestinationGuidance");g0.transform.SetParent(root,false);g0.transform.position=Vector3.zero;group=g0.transform;var previous=root.Find("Destination_Colour_Guidance");var join=previous.Find("ND_C01_LocalJoin");if(join){var g=UnityEngine.Object.Instantiate(join.gameObject,group);g.name="SF_C01_LocalJoin";g.transform.SetPositionAndRotation(join.position,join.rotation);}previous.gameObject.SetActive(false);root.Find("Remaining_DestinationGuidance").gameObject.SetActive(false);
 foreach(var r in plan["routes"]){var ps=r["points"].Select(V).ToArray();var geo=new Geo();geo.Ribbon(ps,.10f);float total=0,next=2.2f;for(int i=1;i<ps.Length;i++){float len=Vector3.Distance(ps[i-1],ps[i]);if(len<.00001f)continue;var f=(ps[i]-ps[i-1])/len;var right=Vector3.Cross(Vector3.up,f);while(next<=total+len){var p=Vector3.Lerp(ps[i-1],ps[i],(next-total)/len);geo.Stroke(p-f*.14f-right*.075f,p+f*.14f,.025f);geo.Stroke(p-f*.14f+right*.075f,p+f*.14f,.025f);next+=3.5f;}total+=len;}Add("SF_Guide_"+(string)r["id"],geo,paints[(string)r["code"]]);}
 foreach(var l in plan["labels"]){var geo=new Geo();geo.Rect(V(l["position"]),new Vector3((float)l["forward"][0],0,(float)l["forward"][1]),(float)l["width"],(float)l["length"]);Add("SF_Label_"+(string)l["id"],geo,labels[(string)l["code"]]);}
 foreach(var l in plan["legends"]){string code=(string)l["code"];var geo=new Geo();geo.Rect(V(l["position"]),new Vector3((float)l["forward"][0],0,(float)l["forward"][1]),(float)l["width"],(float)l["length"]);Add("SF_Legend_"+code,geo,Mat("SF_Legend_"+code,Color.white,"SF_Legend_"+code));}
 EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);var result=new{routes=plan["routes"].Count(),labels=plan["labels"].Count(),legends=plan["legends"].Count(),destinations=15};File.WriteAllText(Repo+"/Docs/검수/2026-11-08_B5_SpatialRefinement/guides_apply.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
